    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof supplierBillsReverseReview>>, TError,SupplierBillsReverseReviewMutationVariables, TContext>, request?: SecondParameter<typeof apiRequest>}
): UseMutationOptions<Awaited<ReturnType<typeof supplierBillsReverseReview>>, TError,SupplierBillsReverseReviewMutationVariables, TContext> => {

const mutationKey = getSupplierBillsReverseReviewMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof supplierBillsReverseReview>>, SupplierBillsReverseReviewMutationVariables> = (props) => {
          const {workspace,bill,data} = props ?? {};

          return  supplierBillsReverseReview(workspace,bill,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type SupplierBillsReverseReviewMutationResult = NonNullable<Awaited<ReturnType<typeof supplierBillsReverseReview>>>
    export type SupplierBillsReverseReviewMutationBody = BodyType<ReverseBody>
    export type SupplierBillsReverseReviewMutationError = ErrorType<MessageBody | ValidationErrorBody>
    export type SupplierBillsReverseReviewMutationVariables = {workspace: string;bill: string;data: BodyType<ReverseBody>}

    /**
 * @summary Preview reversing a posted bill (no writes)
 */
export const useSupplierBillsReverseReview = <TError = ErrorType<MessageBody | ValidationErrorBody>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof supplierBillsReverseReview>>, TError,SupplierBillsReverseReviewMutationVariables, TContext>, request?: SecondParameter<typeof apiRequest>}
 , queryClient?: QueryClient): UseMutationResult<
        Awaited<ReturnType<typeof supplierBillsReverseReview>>,
        TError,
        SupplierBillsReverseReviewMutationVariables,
        TContext
      > => {
      return useMutation(getSupplierBillsReverseReviewMutationOptions(options), queryClient);
    }
